// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function testFuzz_property(address newCEO) public {
        vm.assume(newCEO != address(c.ceoAddress()));
        vm.assume(newCEO != address(0));

        address currentCEO = c.ceoAddress();
        vm.prank(currentCEO);
        c.DrugDealer();

        assertEq(c.ceoAddress(), currentCEO);
    }
}
